const clientes = $input.all();

const estadosPrincipais = ["SP", "RJ", "PR", "MG"];

// 1. Filtra os clientes conforme a regra original
const filtrados = clientes.filter(item => {
  const cliente = item.json;

  const status = String(cliente["Status"] ?? "").trim();
  const estado = String(cliente["Estado"] ?? "").trim().toUpperCase();
  const tags = String(cliente["Tags"] ?? "");

  return (
    status === "Ativo" &&
    !estadosPrincipais.includes(estado) &&
    !tags.includes("Veri Visita")
  );
});

// 2. Divide em blocos de no máximo 2.000 clientes
const tamanhoParte = 2000;
const resultado = [];

for (let i = 0; i < filtrados.length; i += tamanhoParte) {
  const parte = filtrados.slice(i, i + tamanhoParte);

  resultado.push({
    json: {
      parte: Math.floor(i / tamanhoParte) + 1,
      totalNaParte: parte.length,
      clientes: parte.map(item => item.json)
    }
  });
}

return resultado;

